contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint value) public payable {
        require(address(this).balance >= value);
        uint balBefore = address(c).balance;
        bool isOwner = (msg.sender == c.owner());
        bool reverted;
        try c.sendMoney{value: value}(target, value) {
