contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint amount) public payable {
        require(target != address(0));
        require(address(this).balance >= amount);
        // Fund C with the amount to be sent.
        (bool ok) = address(c).call{value: amount}("");
        require(ok);
        uint cBefore = address(c).balance;
        uint targetBefore = target.balance;
        bool reverted;
